import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { submitAssessment } from '../services/api';

const initial = {
  sleep_score: 7,
  sleep_variance: 1.5,
  stress_score: 4,
  stress_variance: 1.2,
  walking_pct: 40,
  running_pct: 10,
  stationary_pct: 50,
  activity_level: 6,
};

export default function Assessment() {
  const [form, setForm] = useState(initial);
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const update = (k, v) => setForm({ ...form, [k]: parseFloat(v) || 0 });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const res = await submitAssessment(form);
      setResult(res.data);
    } catch (err) {
      setError(err.response?.data?.error || 'Submission failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2 className="mb-4">Mental Health Assessment</h2>
      {error && <div className="alert alert-danger">{error}</div>}
      {result && (
        <div className="alert alert-success">
          <strong>{result.prediction}</strong> — Confidence: {result.confidence}%
          <button className="btn btn-sm btn-outline-success ms-3" onClick={() => navigate('/recommendations')}>
            View Recommendations
          </button>
        </div>
      )}
      <form onSubmit={handleSubmit} className="card card-mw p-4">
        <div className="row g-3">
          {[
            ['sleep_score', 'Sleep Score (1-10)', 1, 10],
            ['sleep_variance', 'Sleep Variance', 0, 5],
            ['stress_score', 'Stress Score (1-10)', 1, 10],
            ['stress_variance', 'Stress Variance', 0, 5],
            ['walking_pct', 'Walking %', 0, 100],
            ['running_pct', 'Running %', 0, 100],
            ['stationary_pct', 'Stationary %', 0, 100],
            ['activity_level', 'Activity Level (1-10)', 1, 10],
          ].map(([key, label, min, max]) => (
            <div className="col-md-6" key={key}>
              <label className="form-label">{label}</label>
              <input
                type="number"
                step="0.1"
                className="form-control"
                min={min}
                max={max}
                value={form[key]}
                onChange={(e) => update(key, e.target.value)}
                required
              />
            </div>
          ))}
        </div>
        <p className="text-muted small mt-2">Activity percentages should sum to ~100.</p>
        <button className="btn btn-primary mt-3" disabled={loading}>
          {loading ? 'Analyzing...' : 'Submit & Predict'}
        </button>
      </form>
    </div>
  );
}
